import React, { useEffect, useMemo, useRef, useState, useCallback } from "react"
// Standalone Framer Shim for Next.js / React
const useIsStaticRenderer = () => false;
const addPropertyControls = () => {};
const ControlType = {
    Boolean: 'boolean', Number: 'number', String: 'string',
    Color: 'color', Enum: 'enum', Object: 'object',
    Array: 'array', Image: 'image', ResponsiveImage: 'responsiveImage',
    Font: 'font', Transition: 'transition', Link: 'link'
};

import { motion, useReducedMotion } from "framer-motion"

// ============= CONSTANTS =============
const DEFAULT_EYE_SIZE = 160
const DEFAULT_EYE_COLOR = "#ffffff"
const DEFAULT_IRIS_COLOR = "#000000"
const DEFAULT_IRIS_SIZE_PERCENT = 0.456
const ANIMATION_DURATION = 0.15
const ANIMATION_EASING = "cubic-bezier(0.25, 0.46, 0.45, 0.94)"
const JIGGLE_ANIMATION_DURATION = 4
const JIGGLE_ROTATION_DEGREES = 0.5
const RESIZE_DEBOUNCE_MS = 100
const MIN_EYE_SIZE = 20
const MAX_EYE_SIZE = 350
const MIN_IRIS_SIZE_PERCENT = 0.1
const MAX_IRIS_SIZE_PERCENT = 0.9

// ============= EYE MATH =============
const VERTICAL_BOOST_UP = 1.6
const VERTICAL_BOOST_DOWN = 1.0
const MINIMUM_GAP_PIXELS = 4
const GAP_FACTOR = 0.15
const DISTANCE_DAMPING = 0.7 // Optimized for responsive cursor tracking
const HIGHLIGHT_SIZE_FACTOR = 0.25

interface EyeLayoutSettings {
    eyeSize: number
    irisSizePercent: number
    eyeColor: string
    irisColor: string
}

interface EyeLayout {
    eyeballDiameter: number
    irisDiameter: number
    highlightRadius: number
    calculateIrisPosition(params: {
        pointer: { x: number; y: number }
        irisDiameter: number
        eyeCenter: { x: number; y: number }
    }): { x: number; y: number }
}

function hexToRgb(hex: string) {
    // Handle null, undefined, or empty strings
    if (!hex) {
        return { r: 1, g: 1, b: 1 } // Default to white
    }

    // Convert to string in case it's not
    const hexStr = String(hex).trim()

    // Handle rgb/rgba format: rgb(255, 255, 255) or rgba(255, 255, 255, 1)
    if (hexStr.startsWith("rgb")) {
        const match = hexStr.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/)
        if (match) {
            return {
                r: parseInt(match[1], 10) / 255,
                g: parseInt(match[2], 10) / 255,
                b: parseInt(match[3], 10) / 255,
            }
        }
    }

    // Remove # if present
    const clean = hexStr.replace("#", "")

    // Handle shorthand hex: #fff -> #ffffff
    const fullHex =
        clean.length === 3
            ? clean
                  .split("")
                  .map((c) => c + c)
                  .join("")
            : clean

    // Validate hex format
    if (!/^[0-9A-Fa-f]{6}$/.test(fullHex)) {
        return { r: 1, g: 1, b: 1 } // Default to white
    }

    const r = parseInt(fullHex.substring(0, 2), 16)
    const g = parseInt(fullHex.substring(2, 4), 16)
    const b = parseInt(fullHex.substring(4, 6), 16)

    // Check for NaN values
    if (isNaN(r) || isNaN(g) || isNaN(b)) {
        return { r: 1, g: 1, b: 1 } // Default to white
    }

    return {
        r: r / 255,
        g: g / 255,
        b: b / 255,
    }
}

function computeEyeLayout(settings: EyeLayoutSettings): EyeLayout {
    const eyeballDiameter = settings.eyeSize
    const irisDiameter = settings.eyeSize * settings.irisSizePercent
    const highlightRadius =
        settings.eyeSize * settings.irisSizePercent * HIGHLIGHT_SIZE_FACTOR

    return {
        eyeballDiameter,
        irisDiameter,
        highlightRadius,
        calculateIrisPosition({ pointer, irisDiameter, eyeCenter }) {
            const deltaX = pointer.x - eyeCenter.x
            const deltaY = pointer.y - eyeCenter.y

            const eyeballRadius = eyeballDiameter / 2
            const irisRadius = irisDiameter / 2
            const gap = Math.max(MINIMUM_GAP_PIXELS, eyeballRadius * GAP_FACTOR)

            // Check if iris is too large to fit with required gap
            const requiredSpace = irisRadius + gap
            if (requiredSpace >= eyeballRadius) {
                // Iris is too large - constrain it to always maintain gap
                // Scale down the effective iris position to maintain gap
                const scaleFactor = (eyeballRadius - gap) / requiredSpace
                const constrainedIrisRadius = irisRadius * scaleFactor

                // For oversized iris, keep it centered but visually smaller
                return {
                    x: eyeCenter.x - irisRadius,
                    y: eyeCenter.y - irisRadius,
                }
            }

            const maxIrisDistance = eyeballRadius - irisRadius - gap

            // If pointer is at center or very close, place iris at center
            if (Math.abs(deltaX) < 0.01 && Math.abs(deltaY) < 0.01) {
                return {
                    x: eyeCenter.x - irisRadius,
                    y: eyeCenter.y - irisRadius,
                }
            }

            // Use boosted Y only for angle calculation (visual effect)
            const verticalBoost =
                deltaY < 0 ? VERTICAL_BOOST_UP : VERTICAL_BOOST_DOWN
            const boostedDeltaY = deltaY * verticalBoost
            const angle = Math.atan2(boostedDeltaY, deltaX)

            // Use actual (unboosted) deltas for distance to respect boundaries
            const actualDistance = Math.sqrt(deltaX * deltaX + deltaY * deltaY)
            const targetDistance = Math.min(
                actualDistance * DISTANCE_DAMPING,
                maxIrisDistance
            )

            const irisCenterX = eyeCenter.x + Math.cos(angle) * targetDistance
            const irisCenterY = eyeCenter.y + Math.sin(angle) * targetDistance

            return {
                x: irisCenterX - irisRadius,
                y: irisCenterY - irisRadius,
            }
        },
    }
}

// ============= IMAGES (Replace with actual base64 strings) =============
const eyeballImageBase64 =
    "data:image/webp;base64,"

const irisImageBase64 =
    "data:image/webp;base64,"

// ============= COMPONENT =============
/**
 * Props for the PuffyStickerEye component
 * @interface PuffyStickerEyeProps
 */
export interface PuffyStickerEyeProps {
    /** Size of the eyeball in pixels */
    eyeSize?: number
    /** Background color of the eyeball */
    eyeColor?: string
    /** Color of the iris */
    irisColor?: string
    /** Size of iris relative to eye (0.05-0.45) */
    irisSizePercent?: number
    /** Custom CSS class name */
    className?: string
    /** Custom inline styles */
    style?: React.CSSProperties
    /** Accessibility label */
    ariaLabel?: string
}

/**
 * Puffy Sticker Eye Component
 *
 * A single animated puffy sticker eye that tracks mouse/touch movement.
 * Works in both Framer design view and production sites.
 *
 * @framerSupportedLayoutWidth any
 * @framerSupportedLayoutHeight any
 * @framerIntrinsicWidth 160
 * @framerIntrinsicHeight 160
 * @framerDisableUnlink
 */
function PuffyStickerEye({
    eyeSize = DEFAULT_EYE_SIZE,
    eyeColor = DEFAULT_EYE_COLOR,
    irisColor = DEFAULT_IRIS_COLOR,
    irisSizePercent = DEFAULT_IRIS_SIZE_PERCENT,
    className,
    style,
    ariaLabel = "Interactive animated eye",
}: PuffyStickerEyeProps) {
    const containerRef = useRef<HTMLDivElement>(null)

    // Convert iris size from percentage (if needed) to decimal for internal use
    const irisSize =
        irisSizePercent > 1 ? irisSizePercent / 100 : irisSizePercent
    const [mousePos, setMousePos] = useState(() => ({
        x: eyeSize / 2,
        y: eyeSize / 2,
    }))
    const [containerBounds, setContainerBounds] = useState({
        width: eyeSize,
        height: eyeSize,
        left: 0,
        top: 0,
    })
    const [imagesLoaded, setImagesLoaded] = useState(false)
    const [imageError, setImageError] = useState(false)
    const [hasMouseMoved, setHasMouseMoved] = useState(false)

    // Calculate responsive size based on container
    const [actualEyeSize, setActualEyeSize] = useState(eyeSize)

    useEffect(() => {
        setActualEyeSize(eyeSize)
    }, [eyeSize])

    // Performance optimizations
    const isStaticRenderer = useIsStaticRenderer()
    const shouldReduceMotion = useReducedMotion()
    const renderTarget = RenderTarget.current()

    // Unique ID for SVG filters to avoid conflicts
    const filterId = useMemo(
        () => `puffy-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`,
        []
    )

    // Compute eye layout
    const layout = useMemo(
        () =>
            computeEyeLayout({
                eyeSize: actualEyeSize,
                irisSizePercent: irisSize,
                eyeColor,
                irisColor,
            }),
        [actualEyeSize, irisSize, eyeColor, irisColor]
    )

    // Validate images are loadable
    useEffect(() => {
        const validateImages = async () => {
            try {
                const eyeball = new Image()
                const iris = new Image()

                eyeball.src = eyeballImageBase64
                iris.src = irisImageBase64

                await Promise.all([
                    new Promise((resolve, reject) => {
                        eyeball.onload = resolve
                        eyeball.onerror = reject
                    }),
                    new Promise((resolve, reject) => {
                        iris.onload = resolve
                        iris.onerror = reject
                    }),
                ])

                setImagesLoaded(true)
            } catch (error) {
                setImageError(true)
            }
        }

        validateImages()
    }, [])

    useEffect(() => {
        setMousePos({ x: actualEyeSize / 2, y: actualEyeSize / 2 })
    }, [actualEyeSize])

    // Determine if animation should be active
    const shouldAnimate = useMemo(() => {
        // Disable animations for static rendering or reduced motion preference
        if (isStaticRenderer || shouldReduceMotion) return false

        // Disable animations in thumbnail mode
        if (renderTarget === RenderTarget.thumbnail) return false

        return true
    }, [isStaticRenderer, shouldReduceMotion, renderTarget])

    // Keyboard navigation support for accessibility
    const handleKeyDown = useCallback(
        (e: React.KeyboardEvent) => {
            if (!shouldAnimate) return

            const step = 10
            let newX = mousePos.x
            let newY = mousePos.y

            switch (e.key) {
                case "ArrowUp":
                    newY = Math.max(0, newY - step)
                    break
                case "ArrowDown":
                    newY = Math.min(actualEyeSize, newY + step)
                    break
                case "ArrowLeft":
                    newX = Math.max(0, newX - step)
                    break
                case "ArrowRight":
                    newX = Math.min(actualEyeSize, newX + step)
                    break
                case "Home":
                    newX = actualEyeSize / 2
                    newY = actualEyeSize / 2
                    break
                default:
                    return
            }

            e.preventDefault()
            setMousePos({ x: newX, y: newY })
        },
        [shouldAnimate, mousePos, actualEyeSize]
    )

    // Update container bounds with useCallback
    const updateBounds = useCallback(() => {
        if (containerRef.current) {
            const rect = containerRef.current.getBoundingClientRect()
            setContainerBounds({
                width: rect.width,
                height: rect.height,
                left: rect.left,
                top: rect.top,
            })
        }
    }, [])

    // Debounced update bounds
    const debouncedUpdateBounds = useMemo(() => {
        let timeout: NodeJS.Timeout
        return () => {
            clearTimeout(timeout)
            timeout = setTimeout(updateBounds, RESIZE_DEBOUNCE_MS)
        }
    }, [updateBounds])

    // Update container bounds on resize
    useEffect(() => {
        updateBounds()
        window.addEventListener("resize", debouncedUpdateBounds, {
            passive: true,
        })

        return () => {
            window.removeEventListener("resize", debouncedUpdateBounds)
        }
    }, [updateBounds, debouncedUpdateBounds])

    // Pointer move handler with useCallback
    const handlePointerMove = useCallback((e: PointerEvent) => {
        if (!containerRef.current) return

        const rect = containerRef.current.getBoundingClientRect()
        setMousePos({
            x: e.clientX - rect.left,
            y: e.clientY - rect.top,
        })
        setHasMouseMoved(true)
    }, [])

    // Track mouse/touch movement
    useEffect(() => {
        if (!shouldAnimate) return

        document.addEventListener("pointermove", handlePointerMove, {
            passive: true,
        })

        return () => {
            document.removeEventListener("pointermove", handlePointerMove)
        }
    }, [shouldAnimate, handlePointerMove])

    const eyeCenter = {
        x: actualEyeSize / 2,
        y: actualEyeSize / 2,
    }

    const irisPosition = layout.calculateIrisPosition({
        pointer: shouldAnimate && hasMouseMoved ? mousePos : eyeCenter,
        irisDiameter: layout.irisDiameter,
        eyeCenter,
    })

    // Animation variants for subtle jiggle (memoized for performance)
    const jiggleVariants = useMemo(
        () => ({
            animate: {
                rotate: shouldReduceMotion
                    ? 0
                    : [0, -JIGGLE_ROTATION_DEGREES, JIGGLE_ROTATION_DEGREES, 0],
                transition: {
                    duration: JIGGLE_ANIMATION_DURATION,
                    ease: "easeInOut",
                    repeat: shouldReduceMotion ? 0 : Infinity,
                },
            },
        }),
        [shouldReduceMotion]
    )

    // Show error state if images failed to load
    if (imageError) {
        return (
            <div
                ref={containerRef}
                className={className}
                role="img"
                aria-label="Eye component error"
                style={{
                    width: actualEyeSize,
                    height: actualEyeSize,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    backgroundColor: "#f5f5f5",
                    border: "2px dashed #ccc",
                    borderRadius: "50%",
                    ...style,
                }}
            >
                <span style={{ color: "#666", fontSize: "12px" }}>👁️</span>
            </div>
        )
    }

    // Show loading state while images are loading
    if (!imagesLoaded && !imageError) {
        return (
            <div
                ref={containerRef}
                className={className}
                role="img"
                aria-label="Loading eye component"
                style={{
                    width: actualEyeSize,
                    height: actualEyeSize,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    backgroundColor: "#f5f5f5",
                    borderRadius: "50%",
                    ...style,
                }}
            >
                <motion.div
                    animate={{ rotate: 360 }}
                    transition={{
                        duration: 2,
                        repeat: Infinity,
                        ease: "linear",
                    }}
                    style={{
                        width: 20,
                        height: 20,
                        border: "2px solid #ccc",
                        borderTop: "2px solid #333",
                        borderRadius: "50%",
                    }}
                />
            </div>
        )
    }

    return (
        <div
            ref={containerRef}
            className={className}
            role="img"
            aria-label={ariaLabel}
            aria-describedby="eye-keyboard-instructions"
            tabIndex={shouldAnimate ? 0 : -1}
            style={{
                width: actualEyeSize,
                height: actualEyeSize,
                position: "relative",
                cursor: "default",
                outline: "none",
                ...style,
            }}
            onKeyDown={handleKeyDown}
        >
            {/* Screen reader instructions */}
            <span
                id="eye-keyboard-instructions"
                style={{
                    position: "absolute",
                    width: "1px",
                    height: "1px",
                    padding: 0,
                    margin: "-1px",
                    overflow: "hidden",
                    clip: "rect(0, 0, 0, 0)",
                    whiteSpace: "nowrap",
                    border: 0,
                }}
            >
                Use arrow keys to move the eye. Press Home to center.
            </span>
            <svg
                width="100%"
                height="100%"
                viewBox={`0 0 ${actualEyeSize} ${actualEyeSize}`}
                style={{ position: "absolute", top: 0, left: 0 }}
            >
                <defs>
                    {/* Eye Shadow */}
                    <filter
                        id={`eyeShadow-${filterId}`}
                        x="-50%"
                        y="-50%"
                        width="200%"
                        height="200%"
                    >
                        <feDropShadow
                            dx="2"
                            dy="2"
                            stdDeviation="3"
                            floodColor="#000000"
                            floodOpacity="0.25"
                        />
                    </filter>

                    {/* Glossy Highlight */}
                    <radialGradient
                        id={`glossGradient-${filterId}`}
                        cx="40%"
                        cy="20%"
                        r="30%"
                    >
                        <stop
                            offset="0%"
                            stopColor="#ffffff"
                            stopOpacity="0.8"
                        />
                        <stop
                            offset="50%"
                            stopColor="#ffffff"
                            stopOpacity="0.3"
                        />
                        <stop
                            offset="100%"
                            stopColor="#ffffff"
                            stopOpacity="0"
                        />
                    </radialGradient>
                </defs>

                <motion.g
                    filter={`url(#eyeShadow-${filterId})`}
                    variants={shouldAnimate ? jiggleVariants : {}}
                    animate={shouldAnimate ? "animate" : ""}
                >
                    {/* Eyeball with color overlay */}
                    <g>
                        {/* Base grayscale eyeball image */}
                        <image
                            href={eyeballImageBase64}
                            x={eyeCenter.x - layout.eyeballDiameter / 2}
                            y={eyeCenter.y - layout.eyeballDiameter / 2}
                            width={layout.eyeballDiameter}
                            height={layout.eyeballDiameter}
                        />
                        {/* Circular color overlay for tinting */}
                        <circle
                            cx={eyeCenter.x}
                            cy={eyeCenter.y}
                            r={(layout.eyeballDiameter / 2) * 0.89}
                            fill={eyeColor}
                            style={{
                                mixBlendMode: "multiply",
                                pointerEvents: "none",
                            }}
                        />
                    </g>

                    {/* Iris with color overlay */}
                    <motion.g
                        initial={{
                            x: irisPosition.x,
                            y: irisPosition.y,
                        }}
                        animate={{
                            x: irisPosition.x,
                            y: irisPosition.y,
                        }}
                        transition={{
                            duration: ANIMATION_DURATION,
                            ease: ANIMATION_EASING,
                        }}
                    >
                        {/* Base grayscale iris image */}
                        <image
                            href={irisImageBase64}
                            x={0}
                            y={0}
                            width={layout.irisDiameter}
                            height={layout.irisDiameter}
                        />
                        {/* Circular color overlay for tinting */}
                        <circle
                            cx={layout.irisDiameter / 2}
                            cy={layout.irisDiameter / 2}
                            r={(layout.irisDiameter / 2) * 0.88}
                            fill={irisColor}
                            style={{
                                mixBlendMode: "multiply",
                                pointerEvents: "none",
                            }}
                        />
                    </motion.g>

                    {/* Glossy Highlight */}
                    <circle
                        cx={eyeCenter.x}
                        cy={eyeCenter.y}
                        r={layout.highlightRadius}
                        fill={`url(#glossGradient-${filterId})`}
                        opacity="0.8"
                    />
                </motion.g>
            </svg>
        </div>
    )
}

// Add Framer property controls
addPropertyControls(PuffyStickerEye, {
    eyeSize: {
        type: ControlType.Number,
        title: "Eye Size",
        defaultValue: DEFAULT_EYE_SIZE,
        min: MIN_EYE_SIZE,
        max: MAX_EYE_SIZE,
        step: 1,
        unit: "px",
    },
    irisSizePercent: {
        type: ControlType.Number,
        title: "Iris Size",
        defaultValue: DEFAULT_IRIS_SIZE_PERCENT * 100,
        min: MIN_IRIS_SIZE_PERCENT * 100,
        max: MAX_IRIS_SIZE_PERCENT * 100,
        step: 1,
    },
    eyeColor: {
        type: ControlType.Color,
        title: "Eye Color",
        defaultValue: DEFAULT_EYE_COLOR,
    },
    irisColor: {
        type: ControlType.Color,
        title: "Iris Color",
        defaultValue: DEFAULT_IRIS_COLOR,
    },
})

// Export component
export default PuffyStickerEye
